package dev.proofcode.control.data;

import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.ObjectNode;
import java.time.*;
import java.util.*;
import java.util.concurrent.TimeUnit;
import java.util.function.Function;
import org.springframework.stereotype.Component;
import org.springframework.data.redis.connection.*;
import org.springframework.data.redis.connection.lettuce.*;
import org.springframework.data.redis.core.*;

/** A bounded string-key adapter. No arbitrary command, script, FLUSH, KEYS or cross-project key is exposed. */
@Component
public class RedisDataAdapter implements DataAdapter {
    private final DataSecrets secrets;private final ObjectMapper json;
    public RedisDataAdapter(DataSecrets secrets,ObjectMapper json){this.secrets=secrets;this.json=json;}
    private <T>T with(DataResource r,Function<StringRedisTemplate,T> action){JsonNode s=secrets.resolve(r.secretRef);RedisStandaloneConfiguration c=new RedisStandaloneConfiguration(DataPolicy.required(s,"host"),DataPolicy.integer(s,"port",1,65535,6379));c.setDatabase(DataPolicy.integer(s,"database",0,15,0));if(s.has("username"))c.setUsername(s.get("username").asText());if(s.has("password"))c.setPassword(s.get("password").asText());LettuceClientConfiguration client=s.path("tls").asBoolean()?LettuceClientConfiguration.builder().useSsl().and().commandTimeout(Duration.ofSeconds(5)).build():LettuceClientConfiguration.builder().commandTimeout(Duration.ofSeconds(5)).build();LettuceConnectionFactory factory=new LettuceConnectionFactory(c,client);factory.afterPropertiesSet();factory.start();try{StringRedisTemplate t=new StringRedisTemplate(factory);t.afterPropertiesSet();return action.apply(t);}finally{factory.destroy();}}
    private String prefix(DataResource r){return "pc:{"+r.projectId+"}:"+r.environment+":";}
    private String key(DataResource r,JsonNode ir){String key=DataPolicy.required(ir,"key");if(key.length()>512||key.chars().anyMatch(ch->ch<32)||key.startsWith("pc:"))throw DataPolicy.bad("invalid logical cache key");return prefix(r)+key;}
    @Override public JsonNode schema(DataResource r){return json.createObjectNode().put("provider","redis").put("namespace",prefix(r)).put("valueType","string");}
    @Override public Compiled compile(DataResource r,JsonNode ignored,JsonNode ir){
        DataPolicy.fields(ir,"kind","operation","key","value","ttlSeconds","cursor","count");if(!DataPolicy.required(ir,"kind").equals("cache"))throw DataPolicy.bad("invalid cache kind");String op=DataPolicy.required(ir,"operation");if(!Set.of("get","set","delete","expire","scan").contains(op))throw DataPolicy.bad("unsupported cache operation");
        if(op.equals("scan")){if(ir.has("key")||ir.has("value")||ir.has("ttlSeconds"))throw DataPolicy.bad("scan only accepts cursor/count");String cursor=ir.path("cursor").asText("0");if(!cursor.matches("[0-9]{1,20}"))throw DataPolicy.bad("invalid cursor");DataPolicy.integer(ir,"count",1,100,50);}
        else {key(r,ir);if(ir.has("cursor")||ir.has("count"))throw DataPolicy.bad("cursor/count only apply to scan");if(op.equals("set")){if(!ir.path("value").isTextual()||ir.path("value").asText().getBytes(java.nio.charset.StandardCharsets.UTF_8).length>65536)throw DataPolicy.bad("set requires a string of at most 64 KiB");DataPolicy.integer(ir,"ttlSeconds",1,86400,-1);if(!ir.has("ttlSeconds"))throw DataPolicy.bad("set requires ttlSeconds");}else {if(ir.has("value"))throw DataPolicy.bad("value only applies to set");if(op.equals("expire")){if(!ir.has("ttlSeconds"))throw DataPolicy.bad("expire requires ttlSeconds");DataPolicy.integer(ir,"ttlSeconds",1,86400,-1);}else if(ir.has("ttlSeconds"))throw DataPolicy.bad("TTL only applies to set/expire");}}
        String preview=op.equals("scan")?"SCAN project namespace (bounded)":op.toUpperCase(Locale.ROOT)+" "+key(r,ir)+(ir.has("ttlSeconds")?" TTL="+ir.get("ttlSeconds").intValue():"")+(op.equals("set")?" valueHash="+DataPolicy.hash(ir.get("value").asText()):"");
        return new Compiled("cache",preview,"",List.of(),ir);
    }
    private boolean writes(Compiled p){return Set.of("set","delete","expire").contains(p.ir().path("operation").asText());}
    private ObjectNode snapshot(StringRedisTemplate t,String key){if(t.type(key)!=DataType.NONE&&t.type(key)!=DataType.STRING)throw DataPolicy.bad("only string cache values are supported");String value=t.opsForValue().get(key);Long ttl=t.getExpire(key,TimeUnit.MILLISECONDS);if(value!=null&&value.getBytes(java.nio.charset.StandardCharsets.UTF_8).length>65536)throw DataPolicy.bad("cache snapshot is too large");ObjectNode n=json.createObjectNode();if(value==null)n.putNull("value");else n.put("value",value);n.put("hash",valueHash(value));n.put("ttlMs",ttl==null?-2:ttl);n.put("expiresAt",ttl!=null&&ttl>=0?System.currentTimeMillis()+ttl:-1);return n;}
    private String valueHash(String value){return DataPolicy.hash(value==null?"absent":"present:"+value);}
    private JsonNode parse(String s){try{return json.readTree(secrets.unseal(s));}catch(Exception e){throw DataPolicy.bad("invalid cache recovery snapshot");}}
    @Override public String prepare(DataResource r,Compiled p){if(!writes(p))return null;return with(r,t->{ObjectNode n=snapshot(t,key(r,p.ir()));n.put("key",key(r,p.ir()));return secrets.seal(n.toString());});}
    @Override public Outcome execute(DataResource r,Compiled p){return execute(r,p,prepare(r,p));}
    @Override public Outcome execute(DataResource r,Compiled p,String encrypted){
        try{return with(r,t->{String op=p.ir().path("operation").asText();if(op.equals("scan")){List<String> keys=new ArrayList<>();int count=DataPolicy.integer(p.ir(),"count",1,100,50);String cursor=p.ir().path("cursor").asText("0");try(RedisConnection c=Objects.requireNonNull(t.getConnectionFactory()).getConnection()){
                Object nativeConnection=c.getNativeConnection();
                if(!(nativeConnection instanceof io.lettuce.core.api.async.RedisAsyncCommands<?,?>))throw new IllegalStateException("SCAN requires standalone Lettuce connection");
                @SuppressWarnings("unchecked") io.lettuce.core.api.async.RedisAsyncCommands<byte[],byte[]> commands=(io.lettuce.core.api.async.RedisAsyncCommands<byte[],byte[]>)nativeConnection;
                io.lettuce.core.KeyScanCursor<byte[]> page=commands.scan(io.lettuce.core.ScanCursor.of(cursor),new io.lettuce.core.ScanArgs().match(prefix(r)+"*").limit(count)).get(5,TimeUnit.SECONDS);
                byte[] next=bytes(page.getCursor());List<byte[]> returned=page.getKeys();
                int size=0;for(Object value:returned){if(!(value instanceof byte[] raw))throw new IllegalStateException("unexpected SCAN key");size+=raw.length;if(size>262144||keys.size()>=10000)throw new IllegalStateException("SCAN page exceeds bounded payload");String k=new String(raw,java.nio.charset.StandardCharsets.UTF_8);if(k.startsWith(prefix(r)))keys.add(k.substring(prefix(r).length()));}
                return new Outcome("SUCCEEDED",Map.of("keys",keys,"cursor",new String(next,java.nio.charset.StandardCharsets.UTF_8)),null);
            }catch(Exception e){return new Outcome("FAILED_PRECONDITION",Map.of("errorCode","CACHE_SCAN_FAILED"),null);}}
            String key=key(r,p.ir());if(op.equals("get")){ObjectNode snap=snapshot(t,key);Map<String,Object> result=new LinkedHashMap<>();result.put("value",snap.path("value").isNull()?null:snap.path("value").asText());result.put("ttlMs",snap.path("ttlMs").asLong());result.put("hash",snap.path("hash").asText());return new Outcome("SUCCEEDED",result,null);}
            JsonNode before=parse(encrypted);Boolean success=t.execute(new SessionCallback<Boolean>(){@Override @SuppressWarnings("unchecked") public <K,V> Boolean execute(RedisOperations<K,V> operations){RedisOperations<String,String> ops=(RedisOperations<String,String>)(RedisOperations<?,?>)operations;ops.watch(key);String current=ops.opsForValue().get(key);Long ttl=ops.getExpire(key,TimeUnit.MILLISECONDS);if(!matches(before,current,ttl)){ops.unwatch();return false;}ops.multi();if(op.equals("set"))ops.opsForValue().set(key,p.ir().path("value").asText(),Duration.ofSeconds(p.ir().path("ttlSeconds").asLong()));else if(op.equals("delete"))ops.delete(key);else ops.expire(key,Duration.ofSeconds(p.ir().path("ttlSeconds").asLong()));List<Object> results=ops.exec();if(results==null||results.isEmpty())return false;for(Object value:results)if(value instanceof Exception)throw new IllegalStateException("Redis EXEC returned an error");return true;}});
            if(!Boolean.TRUE.equals(success))return Outcome.failed("CACHE_CAS_CONFLICT");
            ObjectNode recovery=(ObjectNode)before.deepCopy();String postValue=op.equals("delete")?null:op.equals("set")?p.ir().path("value").asText():before.path("value").isNull()?null:before.path("value").asText();recovery.put("afterHash",valueHash(postValue));recovery.put("afterExpiresAt",postValue==null?-1:System.currentTimeMillis()+p.ir().path("ttlSeconds").asLong()*1000);int affected=op.equals("set")||!before.path("value").isNull()?1:0;return new Outcome("COMMITTED",Map.of("affectedKeys",affected,"beforeHash",before.path("hash").asText(),"beforeTtlMs",before.path("ttlMs").asLong(),"afterHash",valueHash(postValue)),secrets.seal(recovery.toString()));
        });}catch(Exception e){return new Outcome("COMMIT_UNKNOWN",Map.of("errorCode","CACHE_RESULT_UNKNOWN"),encrypted);}
    }
    private byte[] bytes(String value){return value.getBytes(java.nio.charset.StandardCharsets.UTF_8);}
    private boolean matches(JsonNode before,String value,Long ttl){if(!before.path("hash").asText().equals(valueHash(value)))return false;long expected=before.path("expiresAt").asLong(-1);if(expected<0)return before.path("ttlMs").asLong(-2)==(ttl==null?-2:ttl);return ttl!=null&&ttl>=0&&Math.abs(System.currentTimeMillis()+ttl-expected)<=200;}
    @Override public Outcome compensate(DataResource r,String encrypted){try{return with(r,t->{JsonNode recovery=parse(encrypted);String key=DataPolicy.required(recovery,"key");if(!key.startsWith(prefix(r)))throw DataPolicy.forbidden();Boolean ok=t.execute(new SessionCallback<Boolean>(){@Override @SuppressWarnings("unchecked")public <K,V>Boolean execute(RedisOperations<K,V> operations){RedisOperations<String,String> ops=(RedisOperations<String,String>)(RedisOperations<?,?>)operations;ops.watch(key);String current=ops.opsForValue().get(key);Long ttl=ops.getExpire(key,TimeUnit.MILLISECONDS);long afterExpiry=recovery.path("afterExpiresAt").asLong(-1);if(!recovery.path("afterHash").asText().equals(valueHash(current))||(current!=null&&afterExpiry>=0&&(ttl==null||ttl<0||Math.abs(System.currentTimeMillis()+ttl-afterExpiry)>200))){ops.unwatch();return false;}long oldExpiry=recovery.path("expiresAt").asLong(-1);if(oldExpiry>=0&&oldExpiry<=System.currentTimeMillis()){ops.unwatch();return false;}ops.multi();if(recovery.path("value").isNull())ops.delete(key);else if(oldExpiry>=0)ops.opsForValue().set(key,recovery.path("value").asText(),Duration.ofMillis(oldExpiry-System.currentTimeMillis()));else ops.opsForValue().set(key,recovery.path("value").asText());List<Object> result=ops.exec();return result!=null&&!result.isEmpty()&&result.stream().noneMatch(Exception.class::isInstance);}});return new Outcome(Boolean.TRUE.equals(ok)?"COMPENSATED":"COMPENSATION_CONFLICT",Map.of("restored",Boolean.TRUE.equals(ok)),null);});}catch(Exception e){return new Outcome("COMPENSATION_UNKNOWN",Map.of("errorCode","CACHE_COMPENSATION_UNKNOWN"),null);}}
}
